import math
def control(obs):
    rails=obs['local_map']
    left=rails['left_rail']; right=rails['right_rail']
    mids=[]
    for a,b in ((left,right),(right,left)):
        for p in a:
            if not b: continue
            q=min(b,key=lambda q:(p[0]-q[0])**2+(p[1]-q[1])**2)
            d=math.hypot(p[0]-q[0],p[1]-q[1])
            if 2.5<d<6.5: mids.append(((p[0]+q[0])/2,(p[1]+q[1])/2))
    candidates=[p for p in mids if p[0]>0.5]
    if not candidates: return (0,0)
    u,v=min(candidates,key=lambda p:abs(math.hypot(*p)-3.8))
    desired=math.degrees(math.atan2(5.2*v,u*u+v*v))
    desired=max(-36,min(36,desired))
    h=obs['hitch_deg']
    steer=max(-34,min(34,2.45*h-1.7*desired))
    speed=-0.85 if abs(desired)>10 or abs(h)>15 else -1.1
    return (steer,speed,180)

