import math
def clamp(x,a,b): return max(a,min(b,x))
def control(o):
    lm=o['local_map']; left=lm['left_rail']; right=lm['right_rail']
    centers=[]
    for aa,bb in ((left,right),(right,left)):
        for p in aa:
            if not bb: continue
            q=min(bb,key=lambda q:(p[0]-q[0])**2+(p[1]-q[1])**2)
            d=math.hypot(p[0]-q[0],p[1]-q[1])
            if 2.0<d<5.0: centers.append(((p[0]+q[0])/2,(p[1]+q[1])/2))
    look=1.45
    ahead=[p for p in centers if p[0]>0.25]
    if ahead:
        near=sorted(ahead,key=lambda p:abs(p[0]-look))[:4]
        weights=[1/(0.08+abs(p[0]-look)) for p in near]
        u=sum(p[0]*w for p,w in zip(near,weights))/sum(weights)
        v=sum(p[1]*w for p,w in zip(near,weights))/sum(weights)
        curv=2*v/max(0.4,u*u+v*v)
    else:
        curv=2*math.sin(math.radians(o.get('route',{}).get('bearing_deg',0)))/look
    hd=clamp(math.degrees(math.atan(0.85*curv)),-28,28)
    h=o['hitch_deg']; hr=math.radians(h)
    eq=math.degrees(math.atan2(1.25*math.sin(hr),0.85+0.3*math.cos(hr)))
    steer=clamp(eq+2.0*(h-hd),-45,45)
    speed=-0.48 if abs(h)>20 or abs(h-hd)>10 else -0.65
    if abs(h)>48:
        return (clamp(1.8*h,-45,45),0.5,180)
    return (steer,speed,180)

